+/** Compares recipe requirements at sale time with all recorded consumption in UTC days. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const totals = new Map();
+  function add(itemId, field, qty) {
+    if (!qty) return;
+    if (!totals.has(itemId)) totals.set(itemId, { itemId, actual: 0, theoretical: 0 });
+    totals.get(itemId)[field] += Math.round(qty * 1000);
+  }
+  for (const sale of store.data.sales) {
+    const day = dayOf(sale.soldAt);
+    if (from <= day && day <= to)
+      for (const need of sale.ingredients) add(need.itemId, "theoretical", need.qty);
+  }
+  const items = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = dayOf(m.at);
+    if (from <= day && day <= to) add(items.get(m.batchId), "actual", m.qty);
+  }
+  return [...totals.values()].sort((a, b) => a.itemId - b.itemId).map(({ itemId, actual, theoretical }) => ({
+    itemId, theoretical: theoretical / 1000, actual: actual / 1000, variance: (actual - theoretical) / 1000,
+  }));
+}
