diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..4038b59
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,64 @@
+import { memoryStore } from "../db/store.js";
+import { isDate } from "../dates.js";
+import { AppError } from "../errors.js";
+import { consume } from "../domain/batches.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { parseCsv } from "./csv.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const csvLine = /^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/;
+const instant = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})$/;
+
+function invalid(row, reason) {
+  return new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+/** Imports a whole till file, applying every new ticket only once. */
+export function importSales(store, text) {
+  if (typeof text !== "string") throw invalid(1, "csv must be a string");
+  const staged = memoryStore(store.data);
+  const imported = new Set(store.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  let header;
+  for (const [index, line] of text.split(/\r?\n/).entries()) {
+    const row = index + 1;
+    if (!line.trim()) continue;
+    if (!csvLine.test(line)) throw invalid(row, "invalid CSV");
+    const fields = parseCsv(line)[0].map((field) => field.trim());
+    if (!header) {
+      if (fields.length !== columns.length || !columns.every((key) => fields.includes(key)))
+        throw invalid(row, "expected ticket,soldAt,dishId,qty");
+      header = fields;
+      continue;
+    }
+    if (fields.length !== header.length) throw invalid(row, "wrong number of fields");
+    const sale = Object.fromEntries(header.map((key, i) => [key, fields[i]]));
+    const { ticket, soldAt } = sale;
+    if (!ticket) throw invalid(row, "missing ticket");
+    if (!instant.test(soldAt) || !isDate(soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt)))
+      throw invalid(row, "invalid soldAt");
+    const dishId = Number(sale.dishId);
+    const qty = Number(sale.qty);
+    if (!/^\d+$/.test(sale.qty) || !Number.isSafeInteger(qty) || qty < 1) throw invalid(row, "invalid qty");
+    const dish = staged.data.dishes?.find((d) => d.id === dishId);
+    if (!/^\d+$/.test(sale.dishId) || !dish) throw invalid(row, "unknown dish");
+    if (imported.has(ticket)) continue;
+    const at = new Date(soldAt).toISOString();
+    try {
+      const ingredients = scaled(getRecipe(staged, dish.recipeId), qty);
+      for (const need of ingredients) {
+        if (need.qty > 0) consume(staged, need.itemId, need.qty, { at, ref: `sale:${ticket}` });
+      }
+      staged.data.sales.push({ ticket, soldAt: at, dishId, qty, ingredients });
+    } catch (e) {
+      if (!(e instanceof AppError)) throw e;
+      throw invalid(row, e.code === "not_enough_stock" ? `insufficient stock for ${e.params.item}` : e.code);
+    }
+    tickets.add(ticket);
+    dishes += qty;
+  }
+  if (!header) throw invalid(1, "missing header");
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
